WFJ.Data.add("book", {
  ["9a2153fccb66e714"] = { "DarrowshireへのScourgeの最初の襲撃はまばらだった。略奪を働く骸骨や屍の小集団が村の外れをさまよい、撃退された。\n\nだがScourgeは守り手たちの粘り強さにひるむことなく、同じように応じた。最初の攻撃の波からほどなくして、第二の波が現れたのだ。ghoulの王Horgusのしもべである精鋭のghoulたちが、叫び声を上げて丘から駆け下り、疲弊したDarrowshireの守り手たちとぶつかった。", "." },
  ["9a48d7c0679d3b3f"] = { "Highborne、すなわち遠い昔にAzsharaがQuel'doreiと名付けた者たちは、やがて人々がLordaeronと呼ぶことになる東の地に上陸する。彼らは自分たちの魔法の王国Quel'Thalasを築き、月の崇拝と夜の活動というナイトエルフの教えを捨てるつもりでいた。以後、彼らは太陽を受け入れ、ただハイエルフとしてのみ知られるようになった。", "." },
  ["9a4b17fb05aac4d9"] = { "魔法には4つの掟がある：\n\n魔法は強大である。\n\n魔法は堕落させる。\n\n魔法は中毒になる。\n\n魔法は、秘術を振るう者のもとへTwisting Netherの住人を引き寄せる。\n\nこれらの掟は常に確かなものだ。メイジとしての道を進み続けると決めたなら、これらの掟がお前の運命を支配することになる。\n\nこの警告を無視するほど愚かなら、Northshireの修道院の図書棟まで私に話しに来い。上の階で待っている。\n\n-メイジのトレーナー、Khelden Bremen", "." },
  ["9a57ef9877729204"] = { "時が経つにつれ、Quel'Thalasはハイエルフの努力と魔法の腕前を示す輝かしい記念碑となった。その美しい宮殿はKalimdorの古代の広間と同じ建築様式で造られていたが、土地の自然の地形と織り合わされていた。Quel'Thalasは、エルフたちが創り上げることを切望していた輝く宝石となったのである。", "." },
  ["9a6922aa215756af"] = { "Helgrumへ\n\nわれらの拠点KargathをBadlandsに築くよう命令を出した者に賛辞を送る。兵を鍛えるには理想的な場所だ。過酷な天候、凶暴な野生動物、好戦的な先住民、そして外部からの支援が一切ないこと。ここは、最も優れたウォリアーと斥候だけが生き残って出てくる、るつぼだ。\n\n良い計画だ。よくやった。", "." },
  ["9a9efd5c80387bf5"] = { "ついにArthasは、Kel'Thuzadの遺骸をSunwellの聖なる水に沈めた。この行いによってEternityの力強い水は穢されたが、Kel'Thuzadは魔力を操るlichとして生まれ変わった。はるかに強大な存在としてよみがえったKel'Thuzadは、Lich Kingの計画の次の段階を明かした。", "." },
  ["9aa6dc075ffc2004"] = { "私は戦場でそびえ立つInfernalの前に立ち、Burning Legionの軍勢が四方から迫るのを見たことがある。手に負えないトロールの一団など、Dun Moroghの丘にいる野ウサギほどにも害はないように思える。\n\nBarnilにとって大いに安心なことに、我々は何事もなくTkashi Ruinsを通り過ぎた。一行はGreat Seaのほうへ西へ進み、すぐ南にあるRuins of Zul'Kundaを迂回した。海辺の高い崖を登っていくと、我々は最初のRaptorを見つけた。", "." },
  ["9ad192791a7d99ab"] = { "そしてこれが成った暁には、我らの計画の次の段階を始められます。我ら自身の国と、この地域における権力の基盤を得れば、Third Hostを迎える道を整えることができるのです。\n\nまもなく、Legion Lordsは再び空から炎を降らせることで、我らの働きに報いてくださるでしょう！", "." },
})
